import { CUSTOMER_TRANSLATIONS } from './customerTranslations.js';
import { OFFICER_COMPLAINT_TRANSLATIONS } from './officerComplaintTranslations.js';
export { CUSTOMER_TRANSLATIONS, OFFICER_COMPLAINT_TRANSLATIONS };

/**
 * Fallback translator helper
 */
export const getTranslation = (langCode, key, defaultVal = '') => {
  // First check officer complaints dictionary
  const officerDict = OFFICER_COMPLAINT_TRANSLATIONS[langCode] || OFFICER_COMPLAINT_TRANSLATIONS.en;
  if (officerDict && officerDict[key]) {
    return officerDict[key];
  }

  // Then check customer dictionary
  const custDict = CUSTOMER_TRANSLATIONS[langCode] || CUSTOMER_TRANSLATIONS.en;
  if (custDict && custDict[key]) {
    return custDict[key];
  }

  // Then check standard translation table
  const dict = TRANSLATIONS[langCode] || TRANSLATIONS.en;
  if (dict && dict[key]) {
    return dict[key];
  }

  // Fallback to officer English
  if (OFFICER_COMPLAINT_TRANSLATIONS.en && OFFICER_COMPLAINT_TRANSLATIONS.en[key]) {
    return OFFICER_COMPLAINT_TRANSLATIONS.en[key];
  }

  // Fallback to customer English
  if (CUSTOMER_TRANSLATIONS.en && CUSTOMER_TRANSLATIONS.en[key]) {
    return CUSTOMER_TRANSLATIONS.en[key];
  }

  // Fallback to general English
  if (TRANSLATIONS.en && TRANSLATIONS.en[key]) {
    return TRANSLATIONS.en[key];
  }

  return defaultVal || key;
};
